insert into public.questions (
  id, category, measure, subtype, prompt, answer, min, max, scale, unit,
  reference_year, source_title, source_url, explanation, is_daily
) values
  ('games-event-nintendo-company-founded', 'games', 'history', 'event', 'Long before Mario existed, what year was Nintendo founded as a company that sold hand-painted playing cards?', 1889, 1700, 2000, 'linear', 'year', null, 'Britannica Money — Nintendo Company, Ltd.', 'https://www.britannica.com/money/Nintendo-Company-Ltd', 'Nintendo was founded in Kyoto in 1889 to make hanafuda playing cards, nearly a century before it made a single video game.', false),
  ('games-event-pac-man-release', 'games', 'history', 'event', 'In what year did Pac-Man first gobble his way across Japanese arcades?', 1980, 1950, 2010, 'linear', 'year', null, 'Wikipedia — Pac-Man', 'https://en.wikipedia.org/wiki/Pac-Man', 'Pac-Man launched in Japan in May 1980 and reached North America that August, becoming a global pop-culture icon.', false),
  ('games-event-space-invaders-release', 'games', 'history', 'event', 'In what year did Space Invaders launch the golden age of arcade games, reportedly causing a coin shortage in Japan?', 1978, 1950, 2010, 'linear', 'year', null, 'Wikipedia — History of the Nintendo Entertainment System', 'https://en.wikipedia.org/wiki/History_of_the_Nintendo_Entertainment_System', 'Space Invaders was released by Taito in 1978 and became so popular that arcades reportedly ran short of 100-yen coins.', false),
  ('games-event-nes-north-america-launch', 'games', 'history', 'event', 'In what year did the Nintendo Entertainment System launch in North America, reviving an industry many thought was dead?', 1985, 1950, 2020, 'linear', 'year', null, 'Wikipedia — History of the Nintendo Entertainment System', 'https://en.wikipedia.org/wiki/History_of_the_Nintendo_Entertainment_System', 'The NES launched in North America in 1985, two years after the 1983 video game crash had nearly killed the console market.', false),
  ('games-event-playstation-original-launch', 'games', 'history', 'event', 'In what year did Sony''s original PlayStation first go on sale in Japan?', 1994, 1970, 2020, 'linear', 'year', null, 'PlayStation.com — PlayStation History: 1994', 'https://www.playstation.com/en-us/playstation-history/1994-ps-one/', 'The original PlayStation launched in Japan on December 3, 1994, and had sold 100,000 units by the end of its first day.', false),
  ('games-event-xbox-original-launch', 'games', 'history', 'event', 'In what year did Microsoft''s very first Xbox console launch in North America?', 2001, 1970, 2020, 'linear', 'year', null, 'GameSpot — The Evolution Of Xbox Consoles', 'https://www.gamespot.com/gallery/the-evolution-of-xbox-consoles/2900-1322/', 'The original Xbox launched in North America on November 15, 2001, Microsoft''s first major foray into game consoles.', false),
  ('games-event-atari-founded', 'games', 'history', 'event', 'In what year did Nolan Bushnell found Atari, the company behind Pong?', 1972, 1940, 2000, 'linear', 'year', null, 'Wikipedia — Atari, Inc.', 'https://en.wikipedia.org/wiki/Atari,_Inc.', 'Atari was founded in 1972 in Sunnyvale, California, and helped kickstart the entire video arcade industry.', false),
  ('games-event-steam-platform-launch', 'games', 'history', 'event', 'In what year did Valve first launch Steam, now the dominant PC gaming storefront?', 2003, 1970, 2020, 'linear', 'year', null, 'Wikipedia — Steam (service)', 'https://en.wikipedia.org/wiki/Steam_(service)', 'Steam launched in September 2003 as an automatic patcher for Valve''s own games before expanding into a full storefront.', false),
  ('games-event-world-of-warcraft-release', 'games', 'history', 'event', 'In what year did World of Warcraft first launch, kicking off two decades of continuous play in Azeroth?', 2004, 1980, 2020, 'linear', 'year', null, 'Wowpedia — World of Warcraft', 'https://wowpedia.fandom.com/wiki/World_of_Warcraft', 'World of Warcraft launched in North America on November 23, 2004, on the 10th anniversary of the Warcraft franchise.', false),
  ('games-event-pokemon-red-green-japan-release', 'games', 'history', 'event', 'In what year did the very first Pokémon games, Red and Green, launch in Japan?', 1996, 1970, 2020, 'linear', 'year', null, 'Bulbapedia — Pokémon Red and Green Versions', 'https://bulbapedia.bulbagarden.net/wiki/Pok%C3%A9mon_Red_and_Green_Versions', 'Pocket Monsters Red and Green launched in Japan on February 27, 1996, starting a franchise that reached the West two years later.', false),
  ('games-event-monopoly-first-published', 'games', 'history', 'event', 'In what year did Parker Brothers first publish Monopoly?', 1935, 1880, 1980, 'linear', 'year', null, 'Wikipedia — Monopoly (game)', 'https://en.wikipedia.org/wiki/Monopoly_(game)', 'Parker Brothers published Monopoly in 1935 after buying the rights from salesman Charles Darrow and inventor Lizzie Magie.', false),
  ('games-event-fide-founded', 'games', 'history', 'event', 'In what year was FIDE, the international body that governs competitive chess, founded in Paris?', 1924, 1850, 2000, 'linear', 'year', null, 'FIDE — World Chess Federation', 'https://old.fide.com/fide/fide-world-chess-federation.html', 'FIDE was founded in Paris in July 1924, on the closing day of that year''s unofficial Chess Olympiad.', false),
  ('games-event-scrabble-invented', 'games', 'history', 'event', 'In what year did architect Alfred Butts invent the word game that became Scrabble?', 1938, 1880, 1990, 'linear', 'year', null, 'Wikipedia — English-language Scrabble', 'https://en.wikipedia.org/wiki/English-language_Scrabble', 'Butts invented the game in 1938, basing his letter values on a frequency count of letters in The New York Times.', false),
  ('games-event-uno-invented', 'games', 'history', 'event', 'In what year did an Ohio barber invent UNO to settle a family argument over the rules of Crazy Eights?', 1971, 1920, 2010, 'linear', 'year', null, 'The Strong National Museum of Play — America''s Favorite Game and Success Story: Uno!', 'https://www.museumofplay.org/blog/americas-favorite-game-and-success-story-uno/', 'Merle Robbins invented UNO in 1971 in Reading, Ohio, and sold the first copies out of his own barbershop.', false),
  ('games-event-sega-genesis-north-america-launch', 'games', 'history', 'event', 'In what year did the Sega Genesis launch in North America to take on Nintendo?', 1989, 1950, 2020, 'linear', 'year', null, 'Wikipedia — History of the Nintendo Entertainment System', 'https://en.wikipedia.org/wiki/History_of_the_Nintendo_Entertainment_System', 'Sega released its Mega Drive in Japan in 1988 and brought it to North America as the Genesis in 1989.', false),
  ('games-event-gamecube-north-america-launch', 'games', 'history', 'event', 'In what year did the Nintendo GameCube launch in North America?', 2001, 1970, 2020, 'linear', 'year', null, 'Wikipedia (via EPFL Graph Search) — GameCube', 'https://graphsearch.epfl.ch/en/concept/29036/concepts', 'The GameCube launched in Japan in September 2001 and in North America two months later, competing with the PS2 and Xbox.', false),
  ('games-event-psp-japan-launch', 'games', 'history', 'event', 'In what year did Sony''s first handheld, the PlayStation Portable, launch in Japan?', 2004, 1980, 2020, 'linear', 'year', null, 'PlayStation Wiki — PlayStation Portable', 'https://playstation.fandom.com/wiki/PlayStation_Portable', 'The PSP launched in Japan in December 2004, arriving in North America the following March.', false),
  ('games-event-league-of-legends-release', 'games', 'history', 'event', 'In what year did League of Legends officially launch, becoming one of esports'' defining games?', 2009, 1980, 2020, 'linear', 'year', null, 'League of Legends Wiki — League of Legends (game)', 'https://wiki.leagueoflegends.com/en-us/League_of_Legends', 'League of Legends launched on October 27, 2009, after being announced by Riot Games a year earlier.', false),
  ('games-event-magic-the-gathering-first-released', 'games', 'history', 'event', 'In what year did Wizards of the Coast release the very first Magic: The Gathering set?', 1993, 1960, 2020, 'linear', 'year', null, 'ComicBook.com — Magic: The Gathering Card Sells for Over Half a Million Dollars', 'https://comicbook.com/gaming/news/magic-the-gathering-mtg-black-lotus-record-auction-sale-half-million/', 'Magic: The Gathering''s first set, later known as Alpha, was released in 1993, inventing the collectible card game genre.', false),
  ('games-count-ps2-lifetime-sales', 'games', 'quantity', 'count', 'Sony finally confirmed the figure in 2024 — how many PlayStation 2 consoles were sold across its entire lifetime?', 160000000, 10000000, 500000000, 'log', 'count', null, 'List of best-selling game consoles — Wikipedia', 'https://en.wikipedia.org/wiki/List_of_best-selling_game_consoles', 'Sony confirmed in November 2024 that the PS2 sold over 160 million units, making it the best-selling console ever.', false),
  ('games-count-smash-ultimate-roster', 'games', 'quantity', 'count', 'Super Smash Bros. Ultimate boasts the biggest roster in the series — how many playable fighters does it include in total?', 89, 10, 200, 'linear', 'count', null, 'SmashWiki — Super Smash Bros. Ultimate', 'https://www.ssbwiki.com/Super_Smash_Bros._Ultimate', 'Ultimate features 89 playable fighters, including every character who had ever appeared in a previous Smash game.', false),
  ('games-count-catan-hex-tiles', 'games', 'quantity', 'count', 'How many hexagonal terrain tiles make up the classic Settlers of Catan board?', 19, 3, 50, 'linear', 'count', null, 'Britannica — Catan', 'https://www.britannica.com/sports/Catan-board-game', 'Catan''s island is built from 19 hexagonal terrain tiles, each producing a resource except for the single desert tile.', false),
  ('games-count-risk-territories', 'games', 'quantity', 'count', 'How many territories are up for grabs across the six continents of a Risk board?', 42, 10, 100, 'linear', 'count', null, 'US Games — Risk Board Game', 'https://www.usgames.com/p/risk-board-game/', 'The classic Risk map is divided into 42 territories grouped into six continents, all up for conquest.', false),
  ('games-count-trivial-pursuit-categories', 'games', 'quantity', 'count', 'How many colour-coded categories does a player need a wedge from to win at Trivial Pursuit?', 6, 2, 20, 'linear', 'count', null, 'Wikipedia — Trivial Pursuit', 'https://en.wikipedia.org/wiki/Trivial_Pursuit', 'Players collect one wedge from each of six categories, from Geography to Sports & Leisure, to win the game.', false),
  ('games-count-backgammon-points', 'games', 'quantity', 'count', 'How many narrow triangular points make up a backgammon board?', 24, 4, 60, 'linear', 'count', null, 'Wikipedia — Backgammon', 'https://en.wikipedia.org/wiki/Backgammon', 'Each player''s 15 checkers move around 24 points, grouped into four quadrants of six triangles each.', false),
  ('games-count-dnd-standard-dice-set', 'games', 'quantity', 'count', 'A standard Dungeons & Dragons dice set, the polyhedral shapes used across most tabletop RPGs, contains how many individual dice?', 7, 1, 20, 'linear', 'count', null, 'GM Dice — Dungeons & Dragons Dice', 'https://www.gmdice.com/pages/dungeons-dragons-dice', 'The set has seven dice: a d4, d6, d8, d10, d12, d20, and a percentile d10, and became the standard for RPGs generally.', false),
  ('games-count-dnd-5e-core-classes', 'games', 'quantity', 'count', 'The current core Dungeons & Dragons rulebook lets you build a character from how many character classes?', 12, 2, 30, 'linear', 'count', null, 'Evanston Games — Dungeons & Dragons 5E Core Rulebooks', 'https://www.evanstongames.com/products/dungeons-dragons-5e-core-rulebooks', 'The revised core rulebook offers 12 classes, alongside 48 subclasses and dozens of species and backgrounds.', false),
  ('games-count-standard-deck-with-jokers', 'games', 'quantity', 'count', 'Including the jokers, how many cards come in a standard pack of playing cards sold today?', 54, 10, 120, 'linear', 'count', null, 'Toynk — Xbox Playing Cards', 'https://www.toynk.com/products/xbox-playing-cards-52-card-deck-2-jokers', 'A modern pack has 52 playing cards plus 2 jokers, for 54 cards in total, though the jokers sit outside the four suits.', false),
  ('games-mass-ps5-weight', 'games', 'size', 'mass', 'How many kilograms does the original disc-drive PlayStation 5 weigh?', 4.5, 1, 15, 'linear', 'kilogram', null, 'Video Games Chronicle — The rawest PS5 images yet show exactly how big the console is', 'https://www.videogameschronicle.com/news/the-rawest-ps5-images-yet-show-exactly-how-big-the-console-is/', 'Sony''s official specifications list the original PS5 at 4.5 kilograms, noticeably heavier than its Digital Edition.', false),
  ('games-length-ps5-height', 'games', 'size', 'length', 'Standing upright, how tall in metres is a PlayStation 5 console?', 0.39, 0.1, 1, 'linear', 'metre', null, 'Dimensions.com — PlayStation 5', 'https://www.dimensions.com/element/playstation-5', 'The PS5 stands 390 millimetres tall in its upright orientation, making it noticeably taller than earlier PlayStations.', false),
  ('games-length-fide-king-height', 'games', 'size', 'length', 'FIDE''s tournament regulations specify a recommended chess king height — how tall, in metres, should it be?', 0.095, 0.02, 0.3, 'linear', 'metre', null, 'Chess.com — Chess Board Dimensions: Basics and Guidelines', 'https://www.chess.com/article/view/chess-board-dimensions', 'FIDE recommends a king height of 9.5 centimetres, with every other piece''s size scaled proportionally around it.', false),
  ('games-money-gta-v-budget', 'games', 'quantity', 'money', 'Grand Theft Auto V is widely reported as the most expensive video game ever made — what was its combined development and marketing budget, in US dollars?', 265000000, 10000000, 1000000000, 'log', 'usd', '2013', 'Statista — GTA V is the Most Expensive Video Game Ever Produced', 'https://www.statista.com/chart/amp/1466/most-expensive-video-games-of-all-time', 'Rockstar''s budget was reported at $265 million, rivalling a big-budget Hollywood blockbuster, though never officially confirmed.', false),
  ('games-money-dota2-ti2021-prize-pool', 'games', 'quantity', 'money', 'In 2021, Dota 2''s tournament The International crowd-funded the largest prize pool in esports history — how many US dollars did it reach?', 40018400, 1000000, 150000000, 'log', 'usd', '2021', 'Esports Earnings — The International: Dota 2 Championships', 'https://www.esportsearnings.com/leagues/524-the-international/largest-tournaments', 'The International 2021''s prize pool reached just over $40 million, crowd-funded through in-game item sales.', false),
  ('games-money-black-lotus-auction-record', 'games', 'quantity', 'money', 'In 2021, a single signed Magic: The Gathering Black Lotus card sold at public auction for how many US dollars?', 511100, 10000, 2000000, 'log', 'usd', '2021', 'ComicBook.com — Magic: The Gathering Card Sells for Over Half a Million Dollars', 'https://comicbook.com/gaming/news/magic-the-gathering-mtg-black-lotus-record-auction-sale-half-million/', 'The card, signed by illustrator Christopher Rush, sold on eBay for $511,100, tripling the previous public sale record.', false)
on conflict (id) do nothing;
